import random

def simulate(n, rounds):
    p = list(range(n))
    random.shuffle(p)
    s = list(range(n))
    tags = list(p)
    for r in range(rounds):
        # i) Exit
        s = [i for i in s if tags[i] != i]
        if not s:
            return False
        # ii) Pass
        current_tags = [tags[i] for i in s]
        new_tags_dict = {}
        for idx in range(len(s)):
            new_tags_dict[s[(idx+1)%len(s)]] = current_tags[idx]
        for guest_id in s:
            tags[guest_id] = new_tags_dict[guest_id]
    return len(s) > 0

def monte_carlo(n, rounds, trials=100000):
    count = 0
    for _ in range(trials):
        if simulate(n, rounds):
            count += 1
    return count / trials

for n in range(5, 17):
    prob = monte_carlo(n, 4)
    print(f"N={n}, Prob={prob:.4f}")

